it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
  const registry = new ToolRegistry();
  let callCount = 0;
  registry.register(
    {
      name: 'get_weather',
      description: 'Get the weather',
      inputSchema: {
        type: 'object',
        properties: {
          location: {type: 'string'},
        },
        required: ['location'],
      },
    },
    async () => {
      callCount++;
      return 'ok';
    }
  );

  const response = await registry.execute('get_weather', {});

  expect(response.result).toContain('location is required');
  expect(callCount).toBe(0);
});

