it('rejects a wrong-typed property naming the field and expected type', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'tool',
      description: 'd',
      inputSchema: {
        type: 'object',
        properties: {
          count: {type: 'number'},
        },
      },
    },
    async () => 'ok'
  );

  const response = await registry.execute('tool', {count: 'not-a-number'} as any);

  expect(response.result).toContain('count');
  expect(response.result).toContain('number');
});

